import itertools

def solve():
    edges = []
    for i in range(8):
        for j in range(i + 1, 8):
            edges.append((i, j))

    num_edges = len(edges)
    edge_to_idx = {edge: i for i, edge in enumerate(edges)}

    # Constraints:
    # 1. No red K3: For all i < j < k, not (x_{i,j}=0 and x_{j,k}=0 and x_{i,k}=0)
    # 2. No blue K4: For all i < j < k < l, not (x_{i,j}=1 and x_{i,k}=1 and x_{i,l}=1 and x_{j,k}=1 and x_{j,l}=1 and x_{k,l}=1)

    red_k3s = []
    for triplet in itertools.combinations(range(8), 3):
        i, j, k = sorted(triplet)
        red_k3s.append((edge_to_idx[(i, j)], edge_to_idx[(j, k)], edge_to_idx[(i, k)]))

    blue_k4s = []
    for quadruplet in itertools.combinations(range(8), 4):
        i, j, k, l = sorted(quadruplet)
        # Edges: (i,j), (i,k), (i,l), (j,k), (j,l), (k,l)
        blue_k4s.append([
            edge_to_idx[(i, j)], edge_to_idx[(i, k)], edge_to_idx[(i, l)],
            edge_to_idx[(j, k)], edge_to_idx[(j, l)], edge_to_idx[(k, l)]
        ])

    # Backtracking
    coloring = [-1] * num_edges

    def is_valid(edge_idx, color):
        coloring[edge_idx] = color

        # Check red K3
        for e1, e2, e3 in red_k3s:
            if coloring[e1] == 0 and coloring[e2] == 0 and coloring[e3] == 0:
                coloring[edge_idx] = -1
                return False

        # Check blue K4
        for edges_k4 in blue_k4s:
            if all(coloring[e] == 1 for e in edges_k4):
                coloring[edge_idx] = -1
                return False

        return True

    def backtrack(edge_idx):
        if edge_idx == num_edges:
            return True

        for color in [0, 1]:
            if is_valid(edge_idx, color):
                if backtrack(edge_idx + 1):
                    return True
                coloring[edge_idx] = -1
        return False

    if backtrack(0):
        return coloring
    else:
        return None

result = solve()
