def check_solution(coloring):
    edges = []
    for i in range(8):
        for j in range(i + 1, 8):
            edges.append((i, j))

    edge_to_idx = {edge: i for i, edge in enumerate(edges)}

    # Check red K3
    for triplet in itertools.combinations(range(8), 3):
        i, j, k = sorted(triplet)
        e1 = edge_to_idx[(i, j)]
        e2 = edge_to_idx[(j, k)]
        e3 = edge_to_idx[(i, k)]
        if coloring[e1] == 0 and coloring[e2] == 0 and coloring[e3] == 0:
            return False, f"Red K3 found: {i, j, k}"

    # Check blue K4
    for quadruplet in itertools.combinations(range(8), 4):
        i, j, k, l = sorted(quadruplet)
        edges_k4 = [
            edge_to_idx[(i, j)], edge_to_idx[(i, k)], edge_to_idx[(i, l)],
            edge_to_idx[(j, k)], edge_to_idx[(j, l)], edge_to_idx[(k, l)]
        ]
        if all(coloring[e] == 1 for e in edges_k4):
            return False, f"Blue K4 found: {i, j, k, l}"

    return True, "Valid"

